function forceOvernightStoryProve() {
  const flags = state.save.storyFlags || {};
  const cold = ['cold_open_mediate','cold_open_instigate','cold_open_stage'].some(f => flags[f]);
  if (!cold) { toast('No cold_open_* flag'); return; }
  if ((state.save.dayIndex||1) !== 1) { renderOvernight(); return; }
  // Day advance WITHOUT End-evening gate
  state.save.dayIndex = 2;
  state.save.weekNumber = weekNumber();
  state.save.evening = { checkin:false, visits:[], streetEvent:false, errand:false, secondBeat:false, cupDone:false, cupEveDone:false, complete:false };
  state.save.visitedArcToday = {};
  state.save.storyFlags.overnight_story_prove_used = true;
  applyDay2ColdRewrite();
  saveNow();
  renderOvernight({ lines: [], tease: '' });
}

